#!/usr/bin/env python3
"""Build the static C3PH website from centrally maintained content. Python 3, no packages."""
from pathlib import Path
from html import escape as esc
from urllib.parse import quote
import json
import shutil
import sys
from atlas_design import render_home, build_visual_assets
from funding_page import render_funding

ROOT = Path(__file__).resolve().parents[1]
DATA = json.loads((ROOT / 'content/site.json').read_text())
BASE = 'https://sxa582.github.io/c3phwebsite/'
EMAIL = 'c3phteam@houstonmethodist.org'

def e(value): return esc(str(value), quote=True)
def mail(subject): return f'mailto:{EMAIL}?subject={quote(subject)}'
def arrow(): return '<span aria-hidden="true">↗</span>'
def link(url, label, cls='text-link'):
    external = ' target="_blank" rel="noopener noreferrer"' if url.startswith('https://') else ''
    return f'<a class="{cls}" href="{e(url)}"{external}>{e(label)} {arrow()}</a>'
def section_head(label, title, text='', url='', action='Explore all'):
    return f'<div class="section-head"><div><span class="eyebrow">{e(label)}</span><h2>{e(title)}</h2>{f"<p>{e(text)}</p>" if text else ""}</div>{link(url,action) if url else ""}</div>'
def cta():
    return f'''<section class="section contact-editorial"><div class="wrap"><div class="cta-panel"><div><span class="eyebrow">The next question starts here</span><h2>What could we<br>see together?</h2><p>Bring a clinical question, a computational approach, or a new perspective. Explore collaborative research and training with C3PH.</p></div><div><div class="actions">{link('collaborations.html','Start a conversation','button')}{link('collaborations.html#training','Training inquiries','button secondary')}</div></div></div></div></section>'''

NAV = [('index.html','Home'),('focus-areas.html','Research'),('projects.html','Projects'),('publications.html','Publications'),('funding.html','Funding'),('team.html','Team'),('resources.html','Resources'),('news.html','News')]
def page(path, title, description, body):
    nav = ''.join(f'<a href="{url}"'+(' aria-current="page"' if path==url or (path.startswith('project-') and url=='projects.html') else '')+f'>{label}</a>' for url,label in NAV)
    canonical = BASE + path
    markup = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | C3PH</title><meta name="description" content="{e(description)}"><meta name="theme-color" content="#09233d"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:site_name" content="C3PH"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{BASE}assets/social-card.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{e(title)}"><meta name="twitter:description" content="{e(description)}"><meta name="twitter:image" content="{BASE}assets/social-card.png"><link rel="icon" href="assets/c3ph-heart-orange.png" type="image/png"><link rel="apple-touch-icon" href="assets/c3ph-heart-orange.png"><link rel="preload" href="assets/fonts/space-grotesk.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="assets/site.css"><link rel="stylesheet" href="assets/atlas.css"><script src="assets/site.js" defer></script><script src="assets/atlas.js" defer></script><script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@type':'ResearchOrganization','name':'Center for Cardiovascular Computational and Precision Health','alternateName':'C3PH','url':BASE,'email':EMAIL,'parentOrganization':{'@type':'Organization','name':'Houston Methodist DeBakey Heart & Vascular Center'}},ensure_ascii=False)}</script></head>
<body class="page-{path.removesuffix('.html')}"><a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="wrap nav-shell"><a class="brand" href="index.html" aria-label="C3PH home"><span class="brand-identity"><img class="brand-symbol" src="assets/c3ph-heart-orange.png" width="1254" height="1254" alt="" decoding="async"><span class="wordmark">C<span class="wordmark-three">3</span>PH</span></span><span class="institution-mark">HOUSTON METHODIST<br><span>DeBakey Heart &amp; Vascular Center</span></span></a><button class="menu-button" type="button" aria-expanded="false" aria-controls="site-nav">Menu</button><nav class="nav-links" id="site-nav" aria-label="Main navigation">{nav}<a class="nav-cta" href="collaborations.html"{ ' aria-current="page"' if path=='collaborations.html' else ''}>Collaborate {arrow()}</a></nav></div></header><noscript><style>@media(max-width:960px){{.nav-links{{display:flex;position:static;box-shadow:none;max-height:none}}.nav-shell{{flex-wrap:wrap}}.menu-button{{display:none}}}}</style></noscript>
<main id="main">{body}</main>
<footer class="site-footer"><div class="wrap"><div class="footer-grid"><div><a class="brand" href="index.html" aria-label="C3PH home"><span class="brand-identity"><img class="brand-symbol" src="assets/c3ph-heart-orange.png" width="1254" height="1254" alt="" decoding="async"><span class="wordmark">C<span class="wordmark-three">3</span>PH</span></span></a><p>Center for Cardiovascular Computational and Precision Health<br>Houston Methodist DeBakey Heart &amp; Vascular Center<br>Houston, Texas</p></div><div class="footer-links"><h3>Discover</h3><a href="focus-areas.html">Research programs</a><a href="projects.html">Project portfolio</a><a href="publications.html">Selected publications</a><a href="funding.html">Research funding</a><a href="patents.html">Patents &amp; translation</a><a href="resources.html#ecosystem">Data ecosystem</a></div><div class="footer-links"><h3>Connect</h3><a href="team.html">Meet our team</a><a href="collaborations.html">Research collaborations</a><a href="collaborations.html#training">Training inquiries</a><a href="news.html">Research highlights</a><a href="mailto:{EMAIL}">{EMAIL}</a></div></div><div class="footer-bottom"><span>© <span data-current-year>2026</span> C3PH. All rights reserved.</span><span>Computational discovery for precision cardiovascular health.</span></div></div></footer></body></html>'''
    (ROOT / path).write_text(markup.replace("><", ">\n<")+"\n")

def intro(label, title, description, breadcrumb=''):
    return f'<section class="page-hero"><div class="wrap">{f"<div class=breadcrumbs>{breadcrumb}</div>" if breadcrumb else ""}<span class="eyebrow">{e(label)}</span><h1>{e(title)}</h1><p class="lead">{e(description)}</p></div></section>'

PROGRAMS = DATA["programs"]
PROJECTS = DATA["projects"]

def project_card(project):
    pub=DATA['publications'][project['pub']]
    return f'''<article class="story-card"><a class="story-art" href="project-{project['id']}.html" tabindex="-1" aria-hidden="true"><img src="assets/{project['art']}.svg" width="600" height="320" alt="" loading="lazy" decoding="async"></a><div class="story-body"><span class="label">{e(project['topic'])}</span><h3><a href="project-{project['id']}.html">{e(project['title'])}</a></h3><p>{e(project['summary'])}</p>{link('project-'+project['id']+'.html','Explore the study')}<span class="journal-note">{e(pub['journal'])} · {pub['year']}</span></div></article>'''

def programs():
    return '<div class="program-grid">'+''.join(f'<a class="program" href="focus-areas.html#{pid}"><span class="program-number">0{i+1}</span><h3>{e(title)} <span aria-hidden="true">↗</span></h3><p>{e(desc)}</p></a>' for i,(pid,title,desc,_) in enumerate(PROGRAMS))+'</div>'

METRICS=DATA["metrics"]
def metrics():
    return '<div class="metrics">'+''.join(f'<div class="metric"><strong>{n}</strong><span>{label}</span></div>' for n,label in METRICS)+'</div>'

def news_rows():
    items=[('ECG-GPT evaluated across international settings','A collaborative study of diagnostic text generation from ECG images.','project-ecg-gpt.html'),('Looking beyond the coronary calcium score','Cardiac chamber ratios and heart failure risk in MESA.','project-ct-heart-failure.html'),('Transportation noise and incident diabetes','Environmental epidemiology meets cardiometabolic prevention.','project-transportation-noise.html')]
    return ''.join(f'<a class="news-row" href="{url}"><time datetime="2026">2026</time><div><h3>{e(title)}</h3><p>{e(desc)}</p></div><span class="news-arrow" aria-hidden="true">↗</span></a>' for title,desc,url in items)

def home():
    page('index.html','A new view of prevention','C3PH at Houston Methodist connects imaging, ECGs, health records, and environmental data to advance precision cardiovascular health.',render_home(DATA,link,section_head,cta))


def slug(name): return name.split(',')[0].lower().replace(' ','-')

def team():
    cards=[]
    for m in DATA['team']:
        cards.append(f'<article class="person" id="{slug(m["name"])}"><img src="{m["image"]}" width="400" height="364" alt="{e(m["name"])}" loading="lazy" decoding="async"><div class="person-body"><h3>{e(m["name"])}</h3><p class="role">{e(m["role"])}</p><details><summary>About {e(m["name"].split(",")[0])}</summary><p>{e(m["bio"])}</p><div class="pills">'+''.join(f'<span class="pill">{e(t)}</span>' for t in m['tags'])+'</div></details></div></article>')
    page('team.html','Our team','Meet the clinicians, scientists, engineers, and fellows advancing computational and precision cardiovascular health at C3PH.',intro('People','Interdisciplinary by design.','Meet the investigators, scientists, engineers, fellows, and systems experts behind our research.')+f'<section class="section"><div class="wrap"><h2 class="sr-only">Investigators, scientists, engineers, and fellows</h2><div class="team-grid">{"".join(cards)}</div></div></section>'+cta())

def publications():
    topics=sorted(set(p['topic'] for p in DATA['publications']))
    years=sorted(set(p['year'] for p in DATA['publications']),reverse=True)
    filters=f'''<form class="filters" id="publication-filters" role="search" aria-label="Filter selected publications"><div class="field"><label for="publication-search">Search title, author, or journal</label><input type="search" id="publication-search" placeholder="Try ECG, Al-Kindi, or heart failure" autocomplete="off"></div><div class="field"><label for="publication-topic">Research topic</label><select id="publication-topic"><option value="">All topics</option>{''.join(f'<option value="{e(t)}">{e(t)}</option>' for t in topics)}</select></div><div class="field"><label for="publication-year">Publication year</label><select id="publication-year"><option value="">All years</option>{''.join(f'<option value="{y}">{y}</option>' for y in years)}</select></div><button class="filter-reset" type="reset">Clear filters</button></form>'''
    cards=''.join(f'<article class="pub-card" data-topic="{e(p["topic"])}" data-year="{p["year"]}"><span class="label">{e(p["topic"])}</span><h2>{e(p["title"])}</h2><p class="authors">{e(p["authors"])}</p><p class="journal">{e(p["journal"])} · {p["year"]}</p>{link(p["url"],"Read on PubMed")}</article>' for p in DATA['publications'])
    body=intro('Selected publications','Evidence behind the discovery.','Explore selected work by C3PH investigators across imaging, AI, environmental health, prevention, and outcomes research.')+f'<section class="section"><div class="wrap"><noscript><p class="noscript-note">All publications are shown. Enable JavaScript to use search and filters.</p></noscript>{filters}<p class="result-count" id="publication-count" role="status" aria-live="polite" aria-atomic="true">{len(DATA["publications"])} selected publications</p><div class="pub-list">{cards}</div><p class="empty-state" id="publication-empty" hidden>No publications match these filters. Try a broader term or clear the filters.</p></div></section>'
    page('publications.html','Selected publications','Search selected C3PH publications by title, author, journal, topic, and year.',body)

def projects():
    page('projects.html','Project portfolio','Explore published collaborative studies from C3PH investigators in ECG AI, CT phenotyping, retinal imaging, aging, and environmental health.',intro('Project portfolio','Clinical questions. Computational answers.','Explore selected published studies and collaborative research involving C3PH investigators. Each spotlight links to its source publication.')+f'<section class="section"><div class="wrap"><div class="grid-3">{"".join(project_card(p) for p in PROJECTS)}</div><p class="provenance">Study spotlights describe published research. Clinical implementation is a separate stage of evaluation.</p></div></section>'+cta())
    for p in PROJECTS:
        pub=DATA['publications'][p['pub']]
        body=intro(p['topic'],p['title'],p['summary'],'<a href="projects.html">Project portfolio</a> / '+e(p['short']))+f'''<section class="section"><div class="wrap detail-layout"><article class="detail-copy"><img class="large-art" src="assets/{p['art']}.svg" width="600" height="320" alt="Conceptual illustration of {e(p['topic'])}" decoding="async"><h2>The clinical question</h2><p>{e(p['problem'])}</p><h2>The approach</h2><p>{e(p['approach'])}</p><h2>What the study adds</h2><p>{e(p['finding'])}</p><h2>The next question</h2><p>{e(p['question'])}</p><div class="callout"><p>Explore the source publication for study design, estimates, limitations, and full author contributions.</p></div>{link('projects.html','Back to all projects')}</article><aside class="study-info" aria-label="Study details"><span class="status">{e(p['status'])}</span><dl><dt>Research area</dt><dd>{e(p['topic'])}</dd><dt>Selected investigators</dt><dd>{e(p['contributors'])}</dd><dt>Publication</dt><dd>{e(pub['journal'])}, {pub['year']}</dd></dl>{link(pub['url'],'Read the publication','button')}<div class="actions">{link(mail('Research collaboration: '+p['short']),'Discuss this research')}</div></aside></div></section>'''
        page('project-'+p['id']+'.html',p['short'],p['summary'],body)

def focus():
    content=''
    for i,(pid,title,desc,bullets) in enumerate(PROGRAMS):
        content+=f'<article class="focus-detail" id="{pid}"><span class="program-number">0{i+1}</span><div><h2>{e(title)}</h2><div class="pills"><a class="text-link" href="projects.html">Related studies ↗</a></div></div><div><p>{e(desc)}</p><ul>'+''.join(f'<li>{e(b)}</li>' for b in bullets)+'</ul></div></article>'
    diseases=[('ascvd','Atherosclerotic disease'),('diabetes','Diabetes'),('dementia','Dementia & brain health'),('liver','Metabolic liver disease'),('adiposity','Adiposity & body composition'),('ckd','Chronic kidney disease')]
    body=intro('Research programs','Connecting biology, signals, place, and outcomes.','Our interconnected programs bring computational methods to questions in cardiovascular, cardiometabolic, and aging-related health.')+f'<section class="section"><div class="wrap">{content}</div></section><section class="section soft"><div class="wrap">{section_head("Disease areas","A connected view of health.","Research spans cardiovascular disease and its broader cardiometabolic and environmental context.")}<div class="disease-grid">'+''.join(f'<article class="disease"><img src="images/disease-{pid}.jpg" width="58" height="58" alt="" loading="lazy"><h3>{title}</h3></article>' for pid,title in diseases)+'</div></div></section>'+cta()
    page('focus-areas.html','Research programs','Explore C3PH programs in imaging AI, EHR analytics, exposome science, ECG AI, precision prevention, and implementation.',body)

def collaborations():
    pathways=[('Clinicians & investigators','Bring a clinical question or a proposal for collaborative analysis, method development, or external validation.','Research collaboration inquiry'),('Engineering & data science teams','Discuss multimodal modeling, clinical phenotyping, computational imaging, or research infrastructure.','Computational research collaboration'),('Health systems & industry','Explore multicenter evaluation, clinical translation research, and technology development.','Translation and partnership inquiry')]
    cards=''.join(f'<article class="card"><span class="label">0{i+1}</span><h3>{title}</h3><p>{desc}</p>{link(mail(subject),"Contact the team")}</article>' for i,(title,desc,subject) in enumerate(pathways))
    body=intro('Collaborate','Good research starts with a conversation.','C3PH welcomes clinicians, scientists, engineers, health systems, community partners, and industry teams working toward better cardiovascular health.')+f'''<section class="section"><div class="wrap">{section_head('Find your pathway','Build the next study together.')}<div class="grid-3">{cards}</div></div></section><section class="section soft"><div class="wrap translation"><div><span class="eyebrow">Starting a collaboration</span><h2>Tell us what you want to understand.</h2><p>Share a brief overview so the team can identify the relevant expertise and discuss feasibility.</p><a class="contact-address" href="mailto:{EMAIL}">{EMAIL}</a></div><div class="card"><h3>Helpful details to include</h3><ul class="question-list"><li>Your research question and intended clinical or population benefit.</li><li>Your institution, collaborators, and relevant methods or data.</li><li>The expertise or validation support you are seeking.</li><li>Your proposed timeline and funding context, if available.</li></ul><p class="provenance">Describe data at a high level. Do not send patient-level or confidential information by email.</p></div></div></section><section class="section" id="training"><div class="wrap translation"><div><span class="eyebrow">Students, fellows &amp; postdocs</span><h2>Learn at the intersection of medicine and computation.</h2><p class="lead">Explore mentorship in clinical research, data science, imaging AI, environmental health, and outcomes research.</p>{link('team.html','Find relevant expertise')}</div><div class="card"><h3>Training inquiries</h3><p>Contact the team to discuss current availability. Include your CV, training stage, research interests, relevant experience, and anticipated dates.</p>{link(mail('C3PH training and mentorship inquiry'),'Ask about training','button')}<p class="provenance">Availability depends on current projects and mentorship capacity.</p></div></div></section><section class="section soft"><div class="wrap">{section_head('Across institutions','Collaborative science. Shared expertise.','C3PH investigators work with academic collaborators across clinical medicine, engineering, and population health.')}<div class="grid-3"><article class="card"><h3>Houston Methodist</h3><p>Clinical medicine, cardiovascular prevention, imaging, computational research, and outcomes.</p></article><article class="card"><h3>Case Western Reserve University</h3><p>Collaborative imaging, computational methods, and translational technology research.</p></article><article class="card"><h3>Emory University</h3><p>Collaborative computational imaging, retinal phenotyping, and AI research.</p></article></div><p class="provenance">Selected academic collaborations represented in investigator publications and technology records.</p></div></section>'''
    page('collaborations.html','Collaborate & train with C3PH','Explore research collaborations, translation inquiries, and training pathways with C3PH at Houston Methodist.',body)

def resources():
    rows=''.join(f'<tr><td>{label}</td><td>{number}</td><td>{unit}</td></tr>' for (number,label),unit in zip(METRICS,['Patients represented in longitudinal clinical records','ECG records','Cardiac CT studies','Cardiac MRI studies','Echocardiographic studies','Retinal scans']))
    resources=[('Research publications','Browse published methods, study designs, validation results, and source references.','publications.html','Browse publications'),('Study portfolio','Explore clinical questions, research approaches, investigators, and linked papers.','projects.html','Explore studies'),('Software, protocols & methods','Ask the team about study-specific code, protocols, and sharing arrangements. Availability varies by project.',mail('C3PH software, methods, or protocol inquiry'),'Ask about resources'),('Patents & translation','Explore selected technology areas and public intellectual property records.','patents.html','View technology portfolio')]
    body=intro('Resources & capabilities','A foundation for collaborative discovery.','Explore the research ecosystem, computational capabilities, and pathways to published methods and study-specific resources.')+f'<section class="section"><div class="wrap"><h2 class="sr-only">Research resources</h2><div class="resource-list">'+''.join(f'<article class="card"><div><h3>{title}</h3><p>{desc}</p></div>{link(url,label)}</article>' for title,desc,url,label in resources)+f'''</div></div></section><section class="section soft" id="ecosystem"><div class="wrap">{section_head('Data ecosystem','Large-scale, multimodal research holdings.','Clinical records, imaging, ECGs, and environmental linkage support complementary perspectives on health and disease.')}<div class="table-scroll"><table class="data-table"><caption>Approximate center-reported inventory</caption><thead><tr><th scope="col">Modality</th><th scope="col">Reported volume</th><th scope="col">Unit</th></tr></thead><tbody>{rows}</tbody></table></div><p class="provenance">Source: figures reported on the existing C3PH website, accessed October 22, 2026. Counts are approximate and may overlap across modalities; they do not represent a fully paired multimodal cohort. Study-specific availability is assessed during collaboration planning.</p></div></section><section class="section" id="platform"><div class="wrap">{section_head('Computational platform','From secure analysis to rigorous evaluation.','The C3PH computational ecosystem supports harmonization, phenotyping, model development, validation, and clinical translation research.')}<div class="grid-3"><article class="card"><h3>Data engineering</h3><p>Clinical data harmonization, imaging pipelines, cohort development, and geospatial linkage.</p></article><article class="card"><h3>Model development</h3><p>Deep learning, foundation models, natural language processing, radiomics, and multimodal modeling.</p></article><article class="card"><h3>Evaluation &amp; translation</h3><p>External validation, robustness and equity assessment, outcomes research, and clinical workflow evaluation.</p></article></div><div class="callout"><p>Contact C3PH to discuss feasibility, approvals, data access requirements, and study-specific collaboration arrangements.</p></div></div></section>'''+cta()
    page('resources.html','Resources & data ecosystem','Explore C3PH research holdings, computational capabilities, publications, protocols, and collaboration resources.',body)

def news():
    page('news.html','Research highlights','Recent published research involving C3PH investigators across ECG AI, CT imaging, and environmental health.',intro('Research highlights','Ideas moving cardiovascular science forward.','Explore recent publications and collaborative studies involving C3PH investigators.')+f'<section class="section"><div class="wrap">{news_rows()}<p class="provenance">Years refer to publication years. These highlights summarize published research.</p><div class="actions">{link("publications.html","Browse all selected publications","button secondary")}</div></div></section>'+cta())

def patents():
    cards=''
    for p in DATA['patents']:
        record=p.get('record')
        metadata=f'<p class="patent-meta">{e(record["id"])} · {e(record["type"])} · {e(record["date"])}</p>' if record else '<p class="patent-meta">Translational technology area</p>'
        action=link(record['url'],'View public patent record') if record else link(mail('Technology record inquiry: '+p['title']),'Ask about this technology')
        cards+=f'<article class="card"><h2>{e(p["title"])}</h2>{metadata}<p>{e(p["summary"])}</p><div class="pills">'+''.join(f'<span class="pill">{e(t)}</span>' for t in p['tags'])+f'</div><div class="actions">{action}</div></article>'
    body=intro('Patents & translation','Turning computational ideas into technologies.','Selected intellectual property and translational technology areas involving C3PH investigators and academic collaborators.')+f'<section class="section"><div class="wrap"><div class="patent-list">{cards}</div><p class="provenance">Linked identifiers distinguish granted patent publications from published applications. Publication type is not a statement of current enforceability or licensing availability. Records reviewed October 22, 2026; rights and licensing are handled by the relevant institutions.</p></div></section><section class="section soft"><div class="wrap translation"><div><span class="eyebrow">Technology partnerships</span><h2>Explore the path to translation.</h2><p>Discuss research collaborations, validation studies, and technology-specific inquiries with C3PH.</p></div><div>{link(mail('C3PH translation or licensing inquiry'),'Contact the team','button')}</div></div></section>'
    page('patents.html','Patents & translation','Explore selected C3PH investigator technology areas and linked patent records in computational imaging, risk prediction, and clinical AI.',body)

def assets():
    dest=ROOT/'assets'
    dest.mkdir(exist_ok=True)
    def svg(body): return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 320"><defs><pattern id="grid" width="24" height="24" patternUnits="userSpaceOnUse"><path d="M24 0H0V24" fill="none" stroke="#ffffff" stroke-opacity=".045"/></pattern><radialGradient id="glow"><stop stop-color="#21747a"/><stop offset="1" stop-color="#0b2a45"/></radialGradient></defs><rect width="600" height="320" fill="url(#glow)"/><rect width="600" height="320" fill="url(#grid)"/>'+body+'</svg>'
    ecg='<g stroke="#71d6bd" fill="none" stroke-width="3" stroke-linejoin="round"><path d="M45 110h65l12-8 15 16 18-64 18 118 15-62h40l12-8 15 16 18-64 18 118 15-62h65l12-8 15 16 18-64 18 118 15-62h65"/><path opacity=".4" d="M45 220h65l12-8 15 16 18-38 18 65 15-35h40l12-8 15 16 18-38 18 65 15-35h65l12-8 15 16 18-38 18 65 15-35h65"/></g>'
    ct='<g fill="none"><ellipse cx="300" cy="160" rx="137" ry="122" stroke="#9bb2c2" stroke-width="2"/><ellipse cx="300" cy="160" rx="116" ry="102" fill="#193d55" stroke="#89a7b6"/><path d="M301 86c-38-26-81 14-62 56l62 87c22-34 56-62 65-91 14-44-33-70-65-52Z" fill="#195b6b" stroke="#70d8bb" stroke-width="3"/><path d="M301 98v112M256 126l84 48M265 174l72-51" stroke="#9ec7c6" opacity=".6"/><circle cx="300" cy="160" r="151" stroke="#4a8c98" stroke-dasharray="4 12"/><path d="M80 160h60m320 0h60M300 5v25m0 260v25" stroke="#70d8bb"/></g>'
    retina='<g fill="none" stroke-linecap="round"><circle cx="300" cy="160" r="125" fill="#143c52" stroke="#418391"/><circle cx="273" cy="160" r="15" fill="#c3e4d2" stroke="#71d6bd"/><g stroke="#71d6bd" stroke-width="3"><path d="M273 160c19-38 41-59 95-76m-95 76c27-11 67-13 125 8m-125-8c23 48 56 63 95 78m-95-78c-35-25-58-42-58-72m58 72c-35 15-44 45-46 79"/><path d="m310 110 8-35m14 24 34 13m-24 57 22 30m-52-2-6 43m-65-101-28 12m27-32-2-25" stroke-width="2"/></g><circle cx="300" cy="160" r="144" stroke="#4a8c98" stroke-dasharray="4 12"/></g>'
