def funding():
    data = json.loads((ROOT / 'content/funding.json').read_text())
    page('funding.html', 'Research funding', 'Explore selected NIH and PCORI research support involving C3PH investigators Sadeer Al-Kindi and Khurram Nasir, with award records and source links.', render_funding(data, link))


def build():
    assets()
    build_visual_assets(ROOT)
    home();team();publications();projects();focus();collaborations();resources();news();patents();funding()
    paths=['index.html','focus-areas.html','projects.html','publications.html','funding.html','team.html','resources.html','news.html','collaborations.html','patents.html']+['project-'+p['id']+'.html' for p in PROJECTS]
    (ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{BASE}{p}</loc></url>' for p in paths)+'</urlset>')
    (ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+BASE+'sitemap.xml\n')
    print(f'Built {len(paths)} pages from content/site.json')

if __name__=='__main__':
    build()
    if '--dist' in sys.argv:
        destination=ROOT/'dist'
        destination.mkdir(exist_ok=True)
        for source in ROOT.glob('*.html'): shutil.copy2(source,destination/source.name)
        for folder in ('assets','images'):
            shutil.copytree(ROOT/folder,destination/folder,dirs_exist_ok=True,ignore=shutil.ignore_patterns('*.gif'))
        for name in ('robots.txt','sitemap.xml'): shutil.copy2(ROOT/name,destination/name)
        print('Staged clean static assets in dist/')
